package orchestrator

import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.atomic.AtomicLong
import java.util.concurrent.ConcurrentHashMap

// Circuit Breaker States
enum class CircuitState { CLOSED, OPEN, HALF_OPEN }

data class CircuitConfig(
    val failureThreshold: Int = 5,
    val resetTimeoutMs: Long = 30000,
    val halfOpenMaxCalls: Int = 3
)

class CircuitBreaker(private val config: CircuitConfig = CircuitConfig()) {
    private val failureCount = AtomicInteger(0)
    private val successCount = AtomicInteger(0)
    private val lastFailureTime = AtomicLong(0)
    @Volatile var state: CircuitState = CircuitState.CLOSED
        private set

    fun recordSuccess() {
        if (state == CircuitState.HALF_OPEN) {
            if (successCount.incrementAndGet() >= config.halfOpenMaxCalls) {
                state = CircuitState.CLOSED
                failureCount.set(0)
                successCount.set(0)
            }
        }
    }

    fun recordFailure() {
        lastFailureTime.set(System.currentTimeMillis())
        if (failureCount.incrementAndGet() >= config.failureThreshold) {
            state = CircuitState.OPEN
        }
    }

    fun canExecute(): Boolean {
        return when (state) {
            CircuitState.CLOSED -> true
            CircuitState.OPEN -> {
                if (System.currentTimeMillis() - lastFailureTime.get() > config.resetTimeoutMs) {
                    state = CircuitState.HALF_OPEN
                    successCount.set(0)
                    true
                } else false
            }
            CircuitState.HALF_OPEN -> true
        }
    }
}

// Container lifecycle handler interface
interface ContainerHandler {
    fun execute(context: Map<String, Any>): Result<String>
}

// Registry of approved handler implementations
object HandlerRegistry {
    private val handlers = ConcurrentHashMap<String, ContainerHandler>()
    private val circuitBreakers = ConcurrentHashMap<String, CircuitBreaker>()

    init {
        handlers["restart"] = RestartHandler()
        handlers["scale"] = ScaleHandler()
        handlers["healthcheck"] = HealthCheckHandler()
    }

    fun getHandler(name: String): ContainerHandler? = handlers[name]

    fun getCircuitBreaker(name: String): CircuitBreaker {
        return circuitBreakers.getOrPut(name) { CircuitBreaker() }
    }

    fun registerDynamic(descriptor: HandlerDescriptor): Boolean {
        val handler = descriptor.instantiate() ?: return false
        handlers[descriptor.name] = handler
        return true
    }
}

data class HandlerDescriptor(
    val name: String,
    val className: String,
    val moduleSource: String = "internal"
) {
    fun instantiate(): ContainerHandler? {
        return try {
            val qualifiedName = resolveClassName(className)
            val clazz = Class.forName(qualifiedName)
            val instance = clazz.getDeclaredConstructor().newInstance()
            // Verify the instance implements our interface
            if (instance is ContainerHandler) instance else null
        } catch (e: Exception) {
            null
        }
    }

    private fun resolveClassName(input: String): String {
        // Resolve short names to full qualified names within our package
        // If already qualified (contains dot), validate against allowed packages
        if ("." in input) {
            val allowedPrefixes = listOf("orchestrator.", "orchestrator.handlers.")
            val isAllowed = allowedPrefixes.any { prefix ->
                input.startsWith(prefix)
            }
            return if (isAllowed) input else "orchestrator.$input"
        }
        return "orchestrator.$input"
    }
}

// Orchestrator that processes container events
class ContainerOrchestrator {
    fun processEvent(event: ContainerEvent): Result<String> {
        val handler = HandlerRegistry.getHandler(event.action)
        val breaker = HandlerRegistry.getCircuitBreaker(event.action)

        if (!breaker.canExecute()) {
            return Result.failure(RuntimeException("Circuit open for ${event.action}"))
        }

        if (handler == null) {
            // Attempt dynamic resolution from event metadata
            if (event.metadata.containsKey("handlerClass")) {
                val descriptor = HandlerDescriptor(
                    name = event.action,
                    className = event.metadata["handlerClass"] as String,
                    moduleSource = event.metadata.getOrDefault("source", "external") as String
                )
                if (!HandlerRegistry.registerDynamic(descriptor)) {
                    return Result.failure(RuntimeException("Cannot resolve handler"))
                }
                return processEvent(event)
            }
            return Result.failure(RuntimeException("Unknown action: ${event.action}"))
        }

        return try {
            val result = handler.execute(event.context)
            breaker.recordSuccess()
            result
        } catch (e: Exception) {
            breaker.recordFailure()
            Result.failure(e)
        }
    }
}

data class ContainerEvent(
    val containerId: String,
    val action: String,
    val context: Map<String, Any> = emptyMap(),
    val metadata: Map<String, Any> = emptyMap()
)

// Built-in handlers
class RestartHandler : ContainerHandler {
    override fun execute(context: Map<String, Any>): Result<String> {
        val containerId = context["containerId"] as? String ?: return Result.failure(IllegalArgumentException("Missing containerId"))
        // Simulate container restart
        return Result.success("Container $containerId restarted")
    }
}

class ScaleHandler : ContainerHandler {
    override fun execute(context: Map<String, Any>): Result<String> {
        val replicas = context["replicas"] as? Int ?: 1
        return Result.success("Scaled to $replicas replicas")
    }
}

class HealthCheckHandler : ContainerHandler {
    override fun execute(context: Map<String, Any>): Result<String> {
        return Result.success("Health check passed")
    }
}
